// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        // The reference returns the exact value of the internal mapping.
        // We compare c.hasRole(role, account) with the expected value.
        // Since both are driven by the same contract, we use two calls:
        // one to hasRole, and one to checkRole does not revert as a proxy for internal state.
        // But we need to observe the actual internal state without direct access.
        // Instead, we check that hasRole returns true iff the role was granted via grantRole.
        // However, grantRole requires admin, so we set up DEFAULT_ADMIN_ROLE for this test.
        // We fuzz role and account, grant the role, and verify hasRole returns true.
        // Then we revoke and verify false. This checks the rule over the contract's lifecycle.

        // Ensure account is not address(0) to avoid special semantics.
        vm.assume(account != address(0));
        // Ensure account is not this test contract to avoid self-admin confusion.
        vm.assume(account != address(this));

        // Grant role (we have DEFAULT_ADMIN_ROLE as deployer).
        // The deployer passed to constructor is address(this), which has DEFAULT_ADMIN_ROLE inherited.
        // DEFAULT_ADMIN_ROLE is admin of all roles by default in AccessControl? Not exactly,
        // but the constructor sets TIMELOCK_ADMIN_ROLE admin to itself, etc. We need to manage arbitrary roles.
        // In AccessControl, DEFAULT_ADMIN_ROLE is admin of all roles unless changed.
        // We can grant any role to account using DEFAULT_ADMIN_ROLE.
        c.grantRole(role, account);
        bool hasAfterGrant = c.hasRole(role, account);

        // Revoke role
        c.revokeRole(role, account);
        bool hasAfterRevoke = c.hasRole(role, account);

        // The general rule: after grant, hasRole must be true; after revoke, must be false.
        // In the buggy version, hasRole returns the negation, so after grant it returns false,
        // and after revoke it returns true (since internal mapping becomes false, !false = true).
        // So we assert that both post-grant true and post-revoke false hold in the reference.
        // The bug will fail on at least one of these assertions depending on internal state before grant.
        // To make it a single assertion, we combine: hasAfterGrant should be true AND hasAfterRevoke should be false.
        assertTrue(hasAfterGrant && !hasAfterRevoke);
    }
}

