        vm.assume(role != bytes32(0));
        vm.assume(otherRole != bytes32(0));
        vm.assume(role != otherRole);
        vm.assume(account != address(this));

        // Set up role hierarchy: otherRole is admin of role
        vm.prank(address(c));
        c.updateDelay(0); // needed to make c itself timelock admin, which is needed to grant roles
        bytes32 timelockAdmin = c.TIMELOCK_ADMIN_ROLE();
        vm.prank(address(this));
        c.grantRole(timelockAdmin, address(this));
        vm.prank(address(this));
        c.grantRole(otherRole, account);
        // grantRole on C requires msg.sender to have the admin role of the role being granted
        // So we grant the admin role to our admin (which we already have via setUp)
        // Actually we have PROPOSER_ROLE and EXECUTOR_ROLE with admin TIMELOCK_ADMIN_ROLE, which we as deployer have.
        // But we need to give admin role otherRole to ourselves to later grant role.
        // Since we are timelock admin, we can grant roles.
        vm.prank(address(this));
        c.grantRole(otherRole, address(this));

        // Now grant role to account, which requires caller to have admin role otherRole
        vm.prank(address(this));
        c.grantRole(role, account);

        // The reference returns otherRole, the mutant returns 0
        bytes32 admin = c.getRoleAdmin(role);
        assertTrue(admin == otherRole);
    }
}

